  return (
    <Button
      unstyled
      trimmed
      aria-label={label}
      {...propsRest}
      className={cx(
        'bk',
        { [cl['bk-icon-button']]: !unstyled },
        className,
      )}
    >
      <Icon
        {...iconProps}
        icon={icon}
        className={cx(iconClassName)}
