      dummy_1: `${firstName} ${lastName}`,
      dummy_2: randCompanyName(),
      dummy_3: randCompanyName(),
      dummy_4: randEmail({ firstName, lastName }),
      dummy_5: randJobDescriptor(),
    });
  }

  return data;
};

