                  {endOfTablePlaceholder}
                </td>
              </tr>
            }
          </tbody>
        </table>
      </div>

      {footer &&
        <div className={cx(cl['bk-data-table__footer'])}>
          {footer}
        </div>
      }
    </>
  );
};


